import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import '../styles/dialogues.css';

const Dialogues = () => {
  const { theme } = useParams();
  const { language, nativeLanguage } = useLanguage();
  const [dialogue, setDialogue] = useState(null);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showTranslations, setShowTranslations] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [availableThemes, setAvailableThemes] = useState([]);
  const [visibleThemes, setVisibleThemes] = useState(6);

  const audioRef = useRef(null);
  const progressIntervalRef = useRef(null);
  const dialogueContentRef = useRef(null);

  // Função para reproduzir diálogo completo sequencialmente
  const playDialogue = async () => {
    if (!dialogue || !dialogue.phrases) return;

    setIsPlaying(true);
    setCurrentPhraseIndex(0);

    for (let i = 0; i < dialogue.phrases.length; i++) {
      if (!isPlaying) break;

      setCurrentPhraseIndex(i);
      await playPhrase(i);

      // Pausa entre frases
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    setIsPlaying(false);
    setCurrentPhraseIndex(0);
  };

  // Função para reproduzir frase individual
  const playPhrase = (phraseIndex) => {
    return new Promise((resolve) => {
      if (!dialogue || !dialogue.phrases || !dialogue.phrases[phraseIndex]) {
        resolve();
        return;
      }

      const phrase = dialogue.phrases[phraseIndex];
      const audioFile = phrase.audio;

      if (!audioFile) {
        resolve();
        return;
      }

      const audio = new Audio(`/audio/${audioFile}`);
      audio.volume = volume;

      audio.onended = () => {
        resolve();
      };

      audio.onerror = () => {
        console.warn(`Áudio não encontrado: ${audioFile}`);
        resolve();
      };

      audio.play().catch(error => {
        console.warn('Erro ao reproduzir áudio:', error);
        resolve();
      });
    });
  };

  const playCurrentPhrase = () => {
    playPhrase(currentPhraseIndex);
  };

  const playSpecificPhrase = (phraseIndex) => {
    playPhrase(phraseIndex);
  };

  const pauseDialogue = () => {
    setIsPlaying(false);
    if (audioRef.current) {
      audioRef.current.pause();
    }
  };

  const stopDialogue = () => {
    setIsPlaying(false);
    setCurrentPhraseIndex(0);
    setCurrentTime(0);
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  };

  const toggleTranslations = () => {
    setShowTranslations(!showTranslations);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const handleVolumeChange = (e) => {
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (audioRef.current) {
      audioRef.current.volume = newVolume;
    }
  };

  const loadDialogue = async (themeName) => {
    try {
      const currentLanguage = language || 'pt';
      console.log(`🌐 Carregando diálogo em: ${currentLanguage}`);

      let response = await fetch(`/dialogues/${currentLanguage}/${themeName}.txt`);

      if (!response.ok && currentLanguage !== 'pt') {
        console.warn(`Diálogo não encontrado em ${currentLanguage}, tentando português`);
        response = await fetch(`/dialogues/pt/${themeName}.txt`);
      }

      if (!response.ok) {
        throw new Error(`Diálogo não encontrado: ${themeName}`);
      }

      const text = await response.text();
      const parsedDialogue = parseDialogue(text, themeName, currentLanguage);
      setDialogue(parsedDialogue);
    } catch (error) {
      console.error('Erro ao carregar diálogo:', error);
    }
  };

  const parseDialogue = (text, themeName) => {
    const lines = text.split('\n').filter(line => line.trim());
    const phrases = [];

    for (let i = 0; i < lines.length; i += 3) {
      if (lines[i] && lines[i + 1]) {
        phrases.push({
          speaker: lines[i].trim(),
          text: lines[i + 1].trim(),
          translation: lines[i + 2] ? lines[i + 2].trim() : '',
          audio: `${themeName}_${Math.floor(i / 3) + 1}.mp3`
        });
      }
    }

    return {
      title: themeName.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
      phrases
    };
  };

  const loadAvailableThemes = async () => {
    try {
      const response = await fetch('/dialogues/themes.json');
      if (response.ok) {
        const themes = await response.json();
        setAvailableThemes(themes);
      }
    } catch (error) {
      console.error('Erro ao carregar temas:', error);
    }
  };

  const loadMoreThemes = () => {
    setVisibleThemes(prev => Math.min(prev + 6, availableThemes.length));
  };

  const showLessThemes = () => {
    setVisibleThemes(6);
  };

  useEffect(() => {
    if (theme) {
      loadDialogue(theme);
    }
    loadAvailableThemes();
  }, [theme]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
    };
  }, []);

  if (!dialogue) {
    return (
      <div className="content-below-navbar">
        <div className="page-title-container">
          <h1 className="page-title">Dialogues</h1>
        </div>
        <div className="container">
          <div className="dialogue-container">
            <div className="dialogue-content">
              <p>Carregando diálogo...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="content-below-navbar">
      <div className="page-title-container">
        <h1 className="page-title">Dialogues</h1>
      </div>

      <div className="container">
        <div className="dialogue-container">
          <h2 className="dialogue-title">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <span>{dialogue.title}</span>
          </h2>

          <div className={`dialogue-content ${showTranslations ? 'show-translations' : ''}`} ref={dialogueContentRef}>
            {dialogue.phrases.map((phrase, index) => (
              <div 
                key={index} 
                className={`message ${phrase.speaker === 'User' ? 'message-user' : 'message-other'} ${index === currentPhraseIndex ? 'current-phrase' : ''}`}
                onClick={() => playSpecificPhrase(index)}
              >
                <div className="message-info">
                  <span className="message-sender">{phrase.speaker}</span>
                </div>
                <div className="message-text">{phrase.text}</div>
                {phrase.translation && (
                  <div className="translation-text">{phrase.translation}</div>
                )}
              </div>
            ))}
          </div>

          <div className="media-player">
            <div className="player-controls">
              <button 
                className="player-btn" 
                onClick={playDialogue}
                style={{ display: !isPlaying ? 'inline-flex' : 'none' }}
              >
                <i className="fas fa-play"></i>
              </button>
              <button 
                className="player-btn" 
                onClick={pauseDialogue}
                style={{ display: isPlaying ? 'inline-flex' : 'none' }}
              >
                <i className="fas fa-pause"></i>
              </button>
              <button className="player-btn" onClick={stopDialogue}>
                <i className="fas fa-stop"></i>
              </button>
              <button 
                className={`player-btn ${showTranslations ? 'active' : ''}`} 
                onClick={toggleTranslations}
              >
                <i className="fas fa-language"></i>
              </button>
              <button 
                className={`player-btn ${isFullscreen ? 'active' : ''}`} 
                onClick={toggleFullscreen}
              >
                <i className={`fas ${isFullscreen ? 'fa-compress' : 'fa-expand'}`}></i>
              </button>
              <div className="volume-control">
                <button className="volume-btn">
                  <i className="fas fa-volume-up"></i>
                </button>
                <input 
                  type="range" 
                  min="0" 
                  max="1" 
                  step="0.1" 
                  value={volume}
                  onChange={handleVolumeChange}
                />
              </div>
            </div>
            <div className="progress-container">
              <div className="progress-bar"></div>
              <div className="time-display">
                <span>{Math.floor(currentTime / 60)}:{(currentTime % 60).toString().padStart(2, '0')}</span>
                <span>{Math.floor(totalTime / 60)}:{(totalTime % 60).toString().padStart(2, '0')}</span>
              </div>
            </div>
          </div>
        </div>

        <h2 className="section-title">Escolha Seu Próximo Tema:</h2>

        <div className="theme-grid">
          {availableThemes.slice(0, visibleThemes).map((themeItem, index) => (
            <div key={index} className="theme-card" onClick={() => loadDialogue(themeItem.file)}>
              <div className="theme-icon">
                <i className={themeItem.icon || 'fas fa-comments'}></i>
              </div>
              <h3>{themeItem.title}</h3>
              <p>{themeItem.description}</p>
            </div>
          ))}
        </div>

        <div className="theme-controls">
          {visibleThemes < availableThemes.length && (
            <button className="theme-control-btn" onClick={loadMoreThemes}>
              <i className="fas fa-chevron-down"></i>
              <span>Carregar Mais Temas</span>
            </button>
          )}
          {visibleThemes > 6 && (
            <button className="theme-control-btn" onClick={showLessThemes}>
              <i className="fas fa-chevron-up"></i>
              <span>Mostrar Menos</span>
            </button>
          )}
        </div>

        <div className="text-center">
          <a href="/signup" className="cta-button">Comece a Aprender Agora!</a>
        </div>
      </div>
    </div>
  );
};

export default Dialogues;
